/* Include the enclosing Render header/reference table in the 64 KiB proof. */
uint32_t
fd_wddm_submit_packet_size(uint32_t bo_count, uint32_t cmd_count)
{
   if (bo_count == 0 || bo_count > TU_WDDM_MAX_RENDER_ALLOCATIONS ||
       cmd_count == 0 || cmd_count > TU_WDDM_MAX_SUBMIT_COMMANDS)
      return 0;

   const uint64_t size = sizeof(struct tu_wddm_msm_submit_request) +
      (uint64_t)bo_count * sizeof(struct tu_wddm_msm_submit_bo) +
      (uint64_t)cmd_count * sizeof(struct tu_wddm_msm_submit_command);
   const uint64_t total = size + sizeof(VIOGPU_WDDM_RENDER_COMMAND) +
      (uint64_t)bo_count * sizeof(VIOGPU_WDDM_ALLOCATION_REFERENCE);
   return total <= TU_WDDM_MAX_RENDER_COMMAND_SIZE ? (uint32_t)size : 0;
}

/* Match the exact presumed field patched by the Native Context KMD. */
uint32_t
fd_wddm_submit_bo_patch_offset(uint32_t bo_index)
{
   if (bo_index >= TU_WDDM_MAX_RENDER_ALLOCATIONS)
      return UINT32_MAX;
   return (uint32_t)(sizeof(struct tu_wddm_msm_submit_request) +
      (size_t)bo_index * sizeof(struct tu_wddm_msm_submit_bo) +
      offsetof(struct tu_wddm_msm_submit_bo, presumed));
}

/* Validate the entire logical input before writing any packet byte. */
bool
fd_wddm_build_submit_packet(
   uint32_t queue_id,
   uint32_t fence,
   const struct fd_wddm_submit_bo *bos,
   uint32_t bo_count,
   const struct fd_wddm_submit_cmd *cmds,
   uint32_t cmd_count,
   void *packet,
   uint32_t capacity,
   uint32_t *output_size)
{
   if (output_size == NULL)
      return false;
   *output_size = 0;
   const uint32_t size = fd_wddm_submit_packet_size(bo_count, cmd_count);
   if (queue_id == 0 || fence == 0 || bos == NULL || cmds == NULL ||
       packet == NULL || size == 0 || capacity < size)
      return false;

   const uint32_t access = TU_WDDM_MSM_SUBMIT_BO_READ | TU_WDDM_MSM_SUBMIT_BO_WRITE;
   const uint32_t allowed = access | TU_WDDM_MSM_SUBMIT_BO_DUMP |
                           TU_WDDM_MSM_SUBMIT_BO_NO_IMPLICIT;
   for (uint32_t i = 0; i < bo_count; i++) {
      if (bos[i].size == 0 || (bos[i].flags & access) == 0 ||
          (bos[i].flags & ~allowed) != 0)
         return false;
   }
   for (uint32_t i = 0; i < cmd_count; i++) {
      const struct fd_wddm_submit_cmd *cmd = &cmds[i];
      if (cmd->bo_index >= bo_count || cmd->size == 0 ||
          ((cmd->offset | cmd->size) & 3) != 0 ||
          cmd->offset > bos[cmd->bo_index].size ||
          cmd->size > bos[cmd->bo_index].size - cmd->offset)
         return false;
   }

   struct tu_wddm_msm_submit_request request = {0};
   request.command = TU_WDDM_MSM_CCMD_GEM_SUBMIT;
   request.length = size;
   request.sequence = fence;
   request.flags = TU_WDDM_MSM_PIPE_3D0 | TU_WDDM_MSM_SUBMIT_NO_IMPLICIT;
   request.queue_id = queue_id;
   request.bo_count = bo_count;
   request.command_count = cmd_count;
   request.fence = fence;
   uint8_t *out = packet;
   memcpy(out, &request, sizeof(request));
   uint32_t cursor = (uint32_t)sizeof(request);
   for (uint32_t i = 0; i < bo_count; i++) {
      struct tu_wddm_msm_submit_bo bo = {0};
      bo.flags = bos[i].flags | TU_WDDM_MSM_SUBMIT_BO_NO_IMPLICIT;
      memcpy(out + cursor, &bo, sizeof(bo));
      cursor += (uint32_t)sizeof(bo);
   }
   for (uint32_t i = 0; i < cmd_count; i++) {
      struct tu_wddm_msm_submit_command cmd = {0};
      cmd.type = TU_WDDM_MSM_SUBMIT_CMD_BUF;
      cmd.submit_index = cmds[i].bo_index;
      cmd.submit_offset = cmds[i].offset;
      cmd.size = cmds[i].size;
      memcpy(out + cursor, &cmd, sizeof(cmd));
      cursor += (uint32_t)sizeof(cmd);
   }
   *output_size = size;
   return true;
}

 * API-neutral native-context packet encoder.  It submits no GPU work.
 */
#ifndef FREEDRENO_WDDM_SUBMIT_H
#define FREEDRENO_WDDM_SUBMIT_H
#include "freedreno_wddm_packet.h"
#ifdef __cplusplus
extern "C" {
#endif

struct fd_wddm_submit_bo {
   uint64_t size;
   uint32_t flags;
};

struct fd_wddm_submit_cmd {
   uint32_t bo_index;
   uint32_t offset;
   uint32_t size;
};

/* Return the native packet size, or zero for invalid/beyond-KMD counts. */
uint32_t fd_wddm_submit_packet_size(uint32_t bo_count, uint32_t cmd_count);

/* Return the presumed-IOVA patch offset, or UINT32_MAX for an invalid index. */
uint32_t fd_wddm_submit_bo_patch_offset(uint32_t bo_index);

/* Build a complete native packet with zero host handles/IOVAs for KMD patching.
 * On rejection, output_size is zero and packet bytes remain untouched.
 * Inputs/output/output_size must be valid, non-overlapping caller-owned ranges.
 * No Vulkan object, DRM fd, allocation, lock, fence wait or GPU call is made.
 */
bool fd_wddm_build_submit_packet(
   uint32_t queue_id,
   uint32_t fence,
   const struct fd_wddm_submit_bo *bos,
   uint32_t bo_count,
   const struct fd_wddm_submit_cmd *cmds,
   uint32_t cmd_count,
   void *packet,
   uint32_t capacity,
   uint32_t *output_size);

#ifdef __cplusplus
}
#endif
#endif /* FREEDRENO_WDDM_SUBMIT_H */

#!/usr/bin/env python3
# SPDX-License-Identifier: MIT
"""Enforce the dependency direction and the native submit's production connection."""
from pathlib import Path
import re

HERE = Path(__file__).resolve().parent
SHARED = HERE.parent
FREEDRENO = SHARED.parent


# Ignore comments, but not includes or executable tokens, when checking layering.
def code(text: str) -> str:
    return re.sub(r'/\*.*?\*/|//[^\n]*', '', text, flags=re.S)


# Fail rather than allow a native-backend target to silently depend on Vulkan.
def main() -> None:
    paths = list(SHARED.glob('*.h')) + list(SHARED.glob('*.c')) + list(SHARED.glob('*.cc'))
    for path in paths:
        text = code(path.read_text(encoding='utf-8'))
        if re.search(r'\b(?:Vk[A-Za-z_0-9]+|vk_[A-Za-z_0-9]+|TU_HAS_WDDM)\b', text):
            raise RuntimeError(f'Vulkan integration leaked into {path.name}')
        for include in re.findall(r'^\s*#\s*include\s*([<"][^>"\n]+[>"])', text, re.M):
            if re.search(r'vulkan|zink|xf86drm|drm\.h|freedreno_priv', include):
                raise RuntimeError(f'Forbidden backend dependency: {include}')
    meson = (SHARED / 'meson.build').read_text(encoding='utf-8')
    if any(name in meson for name in ('idep_vulkan', 'libvulkan', 'libtu', 'libdrm', 'libzink')):
        raise RuntimeError('Shared target must not link a graphics API implementation')
    if "tu_link_with += libfreedreno_wddm" not in (FREEDRENO / 'vulkan/meson.build').read_text():
        raise RuntimeError('Turnip is not linked to the shared transport')
    integration = (FREEDRENO / 'vulkan/tu_knl_wddm.cc').read_text()
    if integration.count('fd_wddm_build_submit_packet(') != 1:
        raise RuntimeError('Production submission does not call the shared encoder exactly once')
    if 'bool\ntu_wddm_context_render(' in integration:
        raise RuntimeError('Duplicate low-level Render implementation remains in Vulkan')
    if 'struct tu_wddm_msm_submit_request {' in integration:
        raise RuntimeError('Duplicate wire layout remains in Vulkan')
    print(f'PASS native split: {len(paths)} implementation/header files; no Vulkan/Zink/DRM dependency')


if __name__ == '__main__':
    main()

 * Link the real backend from an API-neutral Windows executable. No GPU calls.
 */
#include "freedreno_wddm.h"
#include "freedreno_wddm_submit.h"
#include <cstdio>

/* Take addresses through volatile objects so release builds retain the symbols. */
int main()
{
   auto volatile render = &tu_wddm_context_render;
   auto volatile device_open = &tu_wddm_device_open;
   auto volatile allocate = &tu_wddm_allocation_create;
   auto volatile wait = &tu_wddm_context_wait_fence;
   auto volatile dispatch = &tu_wddm_runtime_init;
   if (!render || !device_open || !allocate || !wait || !dispatch ||
       fd_wddm_submit_packet_size(1, 1) != 84)
      return 1;
   std::puts("PASS: shared native KMT backend linked without Vulkan/Zink/DRM libraries");
   std::puts("No adapter opened, no GPU submission, no OpenGL context created.");
   return 0;
}
